import type { Request, Response } from 'express';
import type { CatalogueUseCases } from '../../../application/catalogue/CatalogueModule';
import { parseAddProductCommand } from '../../../application/catalogue/productCommandParsers';

export class CatalogueController {
  constructor(private readonly useCases: CatalogueUseCases) {}

  readonly listCatalogue = (_req: Request, res: Response): void => {
    res.json(this.useCases.listCatalogue.execute());
  };

  readonly listStockLevels = (_req: Request, res: Response): void => {
    res.json(this.useCases.listStockLevels.execute());
  };

  readonly addProduct = (req: Request, res: Response): void => {
    const product = this.useCases.addProduct.execute(parseAddProductCommand(req.body));
    res.status(201).json(product);
  };
}

