import type { Request, RequestHandler, Response } from 'express';
import type { OrderAction } from '../../../application/orders/OrderDtos';
import type { OrderUseCases } from '../../../application/orders/OrderModule';
import { parsePlaceOrderCommand } from '../../../application/orders/orderCommandParsers';

type OrderParams = { id: string };

export class OrderController {
  constructor(private readonly useCases: OrderUseCases) {}

  readonly place = (req: Request, res: Response): void => {
    const order = this.useCases.placeOrder.execute(parsePlaceOrderCommand(req.body));
    res.status(201).location(`/orders/${encodeURIComponent(order.id)}`).json(order);
  };

  readonly get = (req: Request<OrderParams>, res: Response): void => {
    res.json(this.useCases.getOrder.execute(req.params.id));
  };

  readonly list = (req: Request, res: Response): void => {
    const status = req.query['status'];
    if (status !== undefined && typeof status !== 'string') {
      res.status(400).json({
        error: { code: 'INVALID_INPUT', message: "'status' must be given at most once" },
      });
      return;
    }
    res.json(this.useCases.listOrders.execute(status));
  };

  changeStatus(action: OrderAction): RequestHandler<OrderParams> {
    return (req, res) => {
      res.json(this.useCases.changeOrderStatus.execute({ orderId: req.params.id, action }));
    };
  }
}

=====SOURCE-END=====

